  'chat.runError.timedOutMessage': "AI đã lâu không có phản hồi mới nên lượt chạy này đã dừng. Vui lòng thử lại sau.",
  'chat.runError.inactivityTimeoutMessage': "AI đã lâu không có phản hồi mới nên lượt chạy này đã dừng. Vui lòng thử lại sau.",
  "chat.runError.emptyOutputMessage": "AI không thể tạo nội dung. Vui lòng bắt đầu lại tác vụ hoặc chuyển mô hình rồi thử lại.",
  "chat.runError.sessionExpiredMessage": "Tác vụ trước đó không thể tiếp tục. Vui lòng bắt đầu lại tác vụ.",
  'chat.runError.gitBashMissingMessage': "Cần có Git Bash để chạy agent này trên Windows nhưng không tìm thấy. Hãy cài Git for Windows rồi thử lại.",
  "chat.runError.cpuUnsupportedMessage": "Bộ xử lý của máy tính này không hỗ trợ các tính năng chương trình yêu cầu. Vui lòng dùng thiết bị đáp ứng yêu cầu hệ thống.",
  "chat.runError.osUnsupportedMessage": "Phiên bản Windows này quá cũ để chạy môi trường AMR. Hãy cập nhật lên Windows 10 phiên bản 1809 (bản dựng 17763) trở lên rồi thử lại.",
  'chat.runError.title.agentCrashed': 'Tác vụ bị gián đoạn bất ngờ',
  "chat.runError.agentCrashedMessage": "Hãy tạo lại hoặc chuyển mô hình rồi thử lại. Nếu tình trạng này tiếp diễn, hãy liên hệ bộ phận hỗ trợ.",
  'chat.runError.title.accountSuspended': 'Tài khoản bị đình chỉ',
  "chat.runError.accountSuspendedMessage": "Để biết lý do hoặc yêu cầu khôi phục tài khoản, hãy liên hệ bộ phận hỗ trợ.",
  "chat.runError.fallbackMessage": "Không thể chạy tác vụ này. Vui lòng thử lại. Nếu vẫn thất bại, hãy liên hệ bộ phận hỗ trợ.",
  "chat.runError.cliSessionRefusedMessage": "Open Design hiện không hỗ trợ phiên bản agent này. Vui lòng chuyển sang phiên bản được hỗ trợ rồi thử lại.",
  'chat.runError.strategyTaskStateMismatchMessage': "Tác vụ này đã bị cổng kiểm tra chất lượng của chiến lược dừng, nên biểu mẫu của lượt này không thể tiếp tục. Hãy thử lại yêu cầu hoặc bắt đầu yêu cầu mới.",
  "chat.runError.agentReplyIncompleteMessage": "Không thể chạy tác vụ này. Vui lòng thử lại. Nếu vẫn thất bại, hãy liên hệ bộ phận hỗ trợ.",
  'chat.runError.noDeliverableMessage': "Agent đã hoàn tất nhưng dự án chưa có tệp nào mở được, nên tác vụ không thể được ghi nhận là đã bàn giao. Nội dung bạn gửi vẫn còn — hãy thử lại hoặc bổ sung một dòng mô tả điều bạn muốn rồi gửi lại.",
  'chat.runError.clarificationRepeatedMessage': "Agent hỏi thêm chi tiết lần thứ hai, nhưng mỗi tác vụ chỉ có một lượt hỏi nên đã dừng tại đây. Câu trả lời của bạn vẫn nằm trong hội thoại — thử lại sẽ bắt đầu yêu cầu từ đầu; thường chỉ cần gộp phần chi tiết bổ sung vào yêu cầu là đủ trong một lượt.",
  "chat.runError.regionNotSupportedMessage": "Nhà cung cấp hiện chưa cung cấp dịch vụ ở khu vực của bạn. Tác vụ hiện tại không thể tiếp tục.",
  'chat.runError.clientEnvironmentMessage': 'Có vẻ yêu cầu đi qua proxy hoặc mạng công ty và {agent} đã từ chối ({cause}). Hãy thử tuyến mạng khác hoặc điều chỉnh proxy trong Cài đặt.',
