  'integrations.tabHint.useEverywhere': 'CLI, HTTP, MCP',
  'integrations.skillsTitle': 'Tích hợp kỹ năng',
  'integrations.skillsBody': 'Việc quản lý tích hợp ở cấp kỹ năng đang được chuyển từ nhánh khác sang. Thẻ này được dành sẵn để MCP, Connectors và phần thiết lập Skills trong tương lai cùng nằm trên một tuyến Tích hợp.',
