  'chat.brandBrowserAssistDesktopOnly': 'Tính năng hỗ trợ trình duyệt cần ứng dụng máy tính để OpenDesign đọc trang trình duyệt đang mở.',
  'chat.brandBrowserAssistReadFailed': 'Không thể đọc trang trình duyệt. Hãy đảm bảo trang thương hiệu đã mở và tải hoàn tất.',
  'chat.memoryWrittenSummary': 'Đã ghi nhớ {count} tùy chọn',
  'chat.brandBrowserAssistMessage': 'OpenDesign cần hỗ trợ trình duyệt để hoàn tất việc trích xuất thương hiệu này. Dùng thẻ bên dưới để mở Trình duyệt, rồi nhấp Thêm, chọn Tải trang xuống, đợi thông báo thành công và dùng thẻ Bước tiếp theo bên trái để tiếp tục trích xuất. Nếu không thấy thẻ, hãy mở thủ công tab Trình duyệt bên phải rồi làm theo Thêm > Tải trang xuống > Tiếp tục trích xuất.',
  'chat.brandBrowserLocalSnapshotMissing': 'Không có ảnh chụp trang đã lưu cho URL này.',
  'chat.brandBrowserLocalSnapshotReadFailed': 'Không thể đọc ảnh chụp trang đã lưu.',
