  'chat.brandBrowserAssistDownloadGuideTitle': 'Đã mở Trình duyệt',
  'chat.brandBrowserAssistDownloadGuideDetails': 'Bước 1: mở hoặc chuyển sang tab Trình duyệt bên phải và hoàn tất mọi bước xác minh người dùng. Bước 2: nhấp Thêm, rồi chọn Tải trang xuống. Bước 3: đợi thông báo lưu ảnh chụp thành công. Bước 4: quay lại thẻ Bước tiếp theo bên trái và nhấp Tiếp tục trích xuất để tiếp tục trích xuất tự động.',
  'brandEnrichment.title': "Tối ưu bằng AI",
  'brandEnrichment.body': "OpenDesign sẽ chạy quá trình trích xuất sâu hơn ở chế độ nền, tự động áp dụng các kỹ năng hệ thống thiết kế phù hợp và cập nhật hệ thống này tại chỗ. Quá trình có thể mất 10-20 phút; bạn vẫn có thể tiếp tục làm việc.",
