  'chat.designToolbox.action.motion-polish.description': 'Đánh giá thời gian, giảm tốc, hiệu năng và phương án dự phòng giảm chuyển động cho chuyển động hiện có.',
  'chat.designToolbox.action.transition-motion.title': 'Thiết kế chuyển cảnh',
