  'chat.designToolbox.action.anti-ai-polish.description': 'Loại bỏ cảm giác rập khuôn, dải màu kiểu AI, các chồng thẻ rẻ tiền và nội dung mơ hồ.',
  'chat.designToolbox.action.visual-polish.title': 'Tinh chỉnh thiết kế / sẵn sàng phát hành',
  'chat.designToolbox.action.visual-polish.badge': 'Tinh chỉnh',
  'chat.designToolbox.action.visual-polish.description': 'Đánh giá thứ bậc thị giác, kiểu chữ, khoảng cách, khả năng đáp ứng, khả năng tiếp cận và chất lượng bàn giao.',
  'chat.designToolbox.action.image-gen.title': 'Tạo hình ảnh / tham chiếu trực quan',
  'chat.designToolbox.action.image-gen.badge': 'Hình ảnh',
  'chat.designToolbox.action.image-gen.description': 'Tạo hình ảnh tham chiếu cho các phần, tài nguyên, biểu tượng, ảnh mạng xã hội hoặc bảng ý tưởng cho trang hiện tại.',
  'chat.designToolbox.action.chart-gen.title': 'Tạo biểu đồ / sơ đồ',
  'chat.designToolbox.action.chart-gen.badge': 'Biểu đồ',
  'chat.designToolbox.action.chart-gen.description': 'Tạo ECharts, React Flow, sơ đồ, bảng điều khiển, bản đồ quan hệ hoặc tài nguyên trực quan hóa dữ liệu.',
  'chat.designToolbox.action.logo-gen.title': 'Tạo logo / bộ nhận diện',
  'chat.designToolbox.action.logo-gen.badge': 'Logo',
  'chat.designToolbox.action.logo-gen.description': 'Tạo các hướng thiết kế logo, chữ thương hiệu, bố cục kết hợp, biểu tượng và câu lệnh cho hệ thống nhận diện thương hiệu hiện tại.',
  'chat.designToolbox.action.plan-outline.title': "Tạo đề cương PPT từ ý tưởng",
  'chat.designToolbox.action.plan-outline.badge': "Lập kế hoạch",
  'chat.designToolbox.action.plan-outline.description': "Chuyển ý tưởng sơ bộ thành đề cương bộ slide Markdown có thể chỉnh sửa trước khi tạo slide.",
  'chat.designToolbox.action.video-gen.title': 'Tạo video / kịch bản chuyển động',
  'chat.designToolbox.action.video-gen.badge': 'Video',
  'chat.designToolbox.action.video-gen.description': 'Chuyển thiết kế thành video ngắn, storyboard Remotion / Hyperframes hoặc câu lệnh sẵn sàng để tạo.',
  'chat.designToolbox.kind.skill': 'Kỹ năng',
  'chat.designToolbox.kind.plugin': 'Plugin',
  'chat.designToolbox.kind.mcp': 'MCP',
  'chat.designToolbox.kind.mcpTemplate': 'Mẫu MCP',
