  'chat.example1Title': 'Bộ slide thuyết trình lưu động',
  'chat.example1Tag': 'Bộ slide',
  'chat.example1Prompt': 'Tạo bộ slide 10 trang để thuyết trình với nhà đầu tư cho một studio thiết kế đang ở giai đoạn hạt giống. Bao gồm trang bìa, vấn đề, insight, sản phẩm, thị trường, sức hút, mô hình kinh doanh, đội ngũ, đề nghị đầu tư và liên hệ. Trình bày chỉn chu theo phong cách biên tập, biểu đồ rõ ràng, câu chuyện mạch lạc và tiết chế phù hợp với buổi gặp nhà đầu tư.',
  'chat.example2Title': 'Trang đích ứng dụng ghi chú',
  'chat.example2Tag': 'Trang đích',
  'chat.example2Prompt': 'Thiết kế trang đích cho ứng dụng ghi chú AI có thể ghi lại cuộc họp, tìm kiếm ý chính và biến ghi chú thành tác vụ. Bao gồm phần mở đầu, bản xem trước sản phẩm, câu chuyện tính năng, bằng chứng xã hội, giá, câu hỏi thường gặp và lời kêu gọi hành động. Phong cách năng suất nhẹ nhàng với lộ trình chuyển đổi rõ ràng.',
  'chat.example3Title': 'Nguyên mẫu ứng dụng thiền trên di động',
  'chat.example3Tag': 'Di động',
  'chat.example3Prompt': 'Tạo nguyên mẫu bốn màn hình di động cho ứng dụng thiền: trang chủ, trình phát buổi thiền, tiến độ và chuỗi ngày liên tục, bộ sưu tập giấc ngủ. Bao gồm các trạng thái làm quen, thanh điều hướng dưới cùng, điều khiển dễ tiếp cận và ghi chú chuyển động nhẹ nhàng để luồng sẵn sàng cho thử nghiệm.',

