  'designFiles.documentTemplate.scenario.mobile': 'Với ứng dụng di động, hãy liệt kê nền tảng mục tiêu, màn hình, mô hình điều hướng, thao tác cử chỉ, mẫu giao diện gốc, kích thước thiết bị, trạng thái và token thiết kế di động.',
  'designFiles.documentTemplate.scenario.slideDeck': 'Với bộ slide, hãy viết dàn ý PPT có phân trang: mỗi slide một mục gồm tiêu đề, mục đích, thông điệp chính, bằng chứng, định hướng hình ảnh, ghi chú thuyết trình và yêu cầu xuất.',
  'designFiles.documentTemplate.scenario.document': 'Với tài liệu, hãy xác định đối tượng đọc, giọng văn, cấu trúc mục, tư liệu nguồn, trích dẫn hoặc dữ liệu, kỳ vọng bố cục và yêu cầu PDF/xuất tệp.',
  'designFiles.documentTemplate.scenario.image': 'Với hình ảnh, hãy nêu chủ thể, tỷ lệ khung hình, bố cục, phong cách hình ảnh, token thương hiệu, tệp tham khảo và các yếu tố cần loại trừ.',
  'designFiles.documentTemplate.scenario.video': 'Với video, hãy phác thảo storyboard gồm cảnh, thời lượng, phụ đề, chuyển động, tài sản, ghi chú âm thanh và định dạng đầu ra.',
  'designFiles.documentTemplate.scenario.hyperframes': 'Với HyperFrames, hãy mô tả sản phẩm chuyển động HTML: cảnh, dòng thời gian, phụ đề, khoảnh khắc phản hồi theo âm thanh, chuyển cảnh và yêu cầu ghi hình/xuất.',
  'designFiles.documentTemplate.scenario.audio': 'Với âm thanh, hãy xác định hướng giọng nói hoặc âm nhạc, thời lượng, tâm trạng, kịch bản hoặc nội dung, nhịp độ, ghi chú phát âm và mục đích sử dụng cuối.',
  'designFiles.documentTemplate.scenario.liveArtifact': 'Với sản phẩm trực tiếp, hãy mô tả nguồn dữ liệu, tần suất làm mới, tiện ích, bộ lọc, tương tác, trạng thái trống/đang tải/lỗi và cảnh báo hoặc tự động hóa.',
  'designFiles.documentTemplate.scenario.designSystem': 'Với hệ thống thiết kế, hãy liệt kê mục tiêu thương hiệu, token, kiểu chữ, màu sắc, khoảng cách, thành phần, tài sản, tài liệu tham khảo và quy tắc cần tuân theo hoặc tránh.',
  'designFiles.documentTemplate.scenario.default': 'Mô tả đối tượng đọc, sản phẩm bàn giao, nội dung cần có, tài liệu tham khảo, giới hạn và tiêu chí hoàn thành.',
  'designFiles.documentTemplate.nextHeading': 'Bước tiếp theo',
  'designFiles.documentTemplate.nextBody': 'Xem lại và chỉnh sửa tài liệu này, sau đó yêu cầu OpenDesign tạo, sửa đổi hoặc vận hành dựa trên tài liệu.',

