  'nextStep.planGenerateBody': "Dùng kế hoạch Markdown đã duyệt làm nguồn chuẩn cho lượt thiết kế tiếp theo.",
  'nextStep.planImproveTitle': "Cải thiện tài liệu",
  'nextStep.planImproveBody': "Hoàn thiện tài liệu kế hoạch hiện tại trước khi tạo sản phẩm cuối cùng.",
  'nextStep.planGeneratePrompt': "Dùng `{file}` làm nguồn chuẩn. Trước tiên, hãy đọc tài liệu và giữ nguyên các quyết định trong đó, sau đó tạo sản phẩm thiết kế cuối cùng phù hợp. Nếu đây là dàn ý trang chiếu, hãy tạo bộ trang chiếu; nếu là kế hoạch PRD/nguyên mẫu, hãy tạo nguyên mẫu hoặc wireframe; nếu là storyboard/tóm tắt sáng tạo, hãy tạo sản phẩm hình ảnh/truyền thông tương ứng. Trước khi tạo, hãy nêu các TODO cản trở hoặc mâu thuẫn mà bạn không thể giải quyết.",
  'nextStep.planImprovePrompt': "Đọc `{file}` và cải thiện ngay trong tài liệu kế hoạch có thể chỉnh sửa. Thu hẹp phạm vi, bổ sung các phần còn yếu, thêm các bước kiểm tra chấp nhận còn thiếu và giữ lại TODO/câu hỏi mở nếu vẫn cần người dùng cung cấp thông tin. Chưa tạo sản phẩm thiết kế cuối cùng.",
  'nextStep.planImproveArtifactTitle': "Cải thiện sản phẩm",
  'nextStep.planImproveArtifactBody': "Tiếp tục hoàn thiện sản phẩm đã tạo thay vì quay lại lập kế hoạch.",
  'nextStep.planImproveArtifactPrompt': "Cải thiện `{artifact}` ngay tại chỗ. Giữ sản phẩm hiện có đang hoạt động và thực hiện các cải tiến có tác động lớn nhất về sản phẩm, hình ảnh, tương tác và nội dung. Giữ nguyên hành vi đang hoạt động tốt, sau đó tóm tắt các tệp đã thay đổi cùng mọi rủi ro còn lại.",
  'nextStep.planMergeTitle': "Đồng bộ tài liệu và sản phẩm",
  'nextStep.planMergeBody': "Đối chiếu kế hoạch với sản phẩm đã tạo để cả hai cùng được hoàn thiện.",
  'nextStep.planMergePrompt': "Đọc đồng thời `{document}` và `{artifact}`. Xem tài liệu là ý định và sản phẩm là bản triển khai hiện tại. Hãy đối chiếu chúng: cập nhật sản phẩm theo các quyết định đã xác nhận, chỉ cập nhật tài liệu ở những chỗ đã lỗi thời và ghi rõ TODO/câu hỏi mở cho mọi điều chưa được giải quyết. Giữ nguyên hành vi hiện có đang hoạt động và tóm tắt thay đổi ở cả hai tệp.",

